/* ---------- Esquí de montaña ---------- */
async function skiData(){if(MP.skiData)return MP.skiData;try{MP.skiData=await json('data/skitour.json',3600000)}catch{MP.skiData={routes:[],outings:[],error:true}}return MP.skiData}
