function fitLine(line,bottom=140){const m=MP.map;if(!m||!line?.length)return;let w=180,e=-180,s=90,n=-90;for(const p of line){w=Math.min(w,p[1]);e=Math.max(e,p[1]);s=Math.min(s,p[0]);n=Math.max(n,p[0])}m.fitBounds([[w,s],[e,n]],{padding:{top:70,left:40,right:40,bottom},maxZoom:15.5,duration:900,pitch:m.getPitch(),bearing:m.getBearing()})}
