function focus(p){MP.pendingFocus=p;const m=MP.map;if(!m)return;const z=Math.min(MP.is3d?14.5:18,p.zoom||Math.max(m.getZoom(),MP.is3d?13.6:14));MP.anim3d=true;m.once('moveend',()=>{MP.anim3d=false});m.flyTo({center:[p.lon,p.lat],zoom:z,pitch:MP.is3d?Math.max(58,m.getPitch()):0,bearing:m.getBearing(),speed:1.4,curve:1.5,essential:true,padding:{top:60,bottom:$('#mpSheet')&&!$('#mpSheet').hidden?220:80,left:0,right:0}});MP.pendingFocus=null}
